  // Architecture Health (domain architects)
  'nav.health': { EN: 'Architecture Health', AR: 'سلامة البنية المؤسسية' },
  'health.title': { EN: 'Architecture Health', AR: 'سلامة البنية المؤسسية' },
  'health.subtitle': { EN: 'How complete, connected and mature each architecture domain of the Repository is, and what to collect next', AR: 'مدى اكتمال كل مجال من مجالات البنية في المستودع وترابطه ونضجه، وما الذي يجب جمعه تالياً' },
  'health.help': { EN: 'Each domain architect assesses its domain of the Repository: whether the recorded information is useful for decisions (placeholders and empty values do not count), whether objects are connected as the Meta Model defines, how much of the active reference architecture is confirmed, and a weighted maturity score. Every number is computed by the platform from your data; nothing is estimated by AI.', AR: 'يقيّم كل معماري مجال مجالَه في المستودع: هل المعلومات المسجلة مفيدة لاتخاذ القرار (القيم الفارغة والقيم المؤقتة مثل TBD لا تُحتسب)، وهل الكائنات مترابطة كما يحدد النموذج الوصفي، وما مقدار ما تأكد من المعمارية المرجعية المعتمدة، ودرجة نضج موزونة. تحسب المنصة كل رقم من بياناتك، ولا يُقدَّر أي رقم بالذكاء الاصطناعي.' },
  'health.ask_copilot': { EN: 'Ask the architects', AR: 'اسأل المعماريين' },
  'health.no_meta_model': { EN: 'Publish the Meta Model to assess architecture health.', AR: 'انشر النموذج الوصفي لتقييم سلامة البنية.' },
