  'health.enterprise': { EN: 'Enterprise', AR: 'المؤسسة' },
  'health.enterprise.title': { EN: 'Domains compared', AR: 'مقارنة المجالات' },
  'health.enterprise.help': { EN: 'Every domain assessed with the same rules, ordered by the gap between its maturity and its target. Open a domain to see the evidence behind its scores.', AR: 'تُقيَّم جميع المجالات بالقواعد نفسها، وتُرتَّب حسب الفجوة بين نضجها والمستوى المستهدف. افتح مجالاً لترى الأدلة التي بُنيت عليها درجاته.' },
  'health.enterprise.heatmap': { EN: 'Maturity criteria by domain', AR: 'معايير النضج حسب المجال' },
  'health.enterprise.heatmap_help': { EN: 'Each cell is one criterion\'s score (0-100) for one domain. "N/A" means the criterion cannot be measured yet, which is different from a score of zero.', AR: 'كل خلية هي درجة معيار واحد (من 0 إلى 100) لمجال واحد. وتعني "غير مقيّم" أن المعيار لا يمكن قياسه بعد، وهذا يختلف عن درجة صفر.' },
